import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.BUwdTBzS.js";const p=JSON.parse('{"title":"标准执行回退机制","description":"","frontmatter":{"title":"标准执行回退机制"},"headers":[],"relativePath":"dev-flow/references/rollback.md","filePath":"dev-flow/references/rollback.md","lastUpdated":null}'),o={name:"dev-flow/references/rollback.md"};function l(h,t,s,n,c,b){return r(),e("div",null,[...t[0]||(t[0]=[a('<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/rollback.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="标准执行回退机制" tabindex="-1">标准执行回退机制 <a class="header-anchor" href="#标准执行回退机制" aria-label="Permalink to &quot;标准执行回退机制&quot;">​</a></h1><blockquote><p>本文件按需加载，不随 flow.md 一起加载。</p></blockquote><table tabindex="0"><thead><tr><th>当前步骤</th><th>问题</th><th>回退到</th></tr></thead><tbody><tr><td>步骤 4</td><td>用户选择「修改」</td><td>步骤 4（更新计划后重新弹出选项）</td></tr><tr><td>步骤 4</td><td>用户选择「换方案」</td><td>步骤 3</td></tr><tr><td>步骤 4</td><td>用户选择「暂存」</td><td>锁定计划 → 写入工作上下文 → 结束当前会话</td></tr><tr><td>步骤 4</td><td>用户选择「取消」</td><td>终止</td></tr><tr><td>步骤 5</td><td>部分执行完成，用户说&quot;继续执行&quot;</td><td>步骤 5（恢复剩余步骤）</td></tr><tr><td>步骤 5</td><td>计划无法执行</td><td>步骤 4（暂停，说明原因，重新汇报）</td></tr><tr><td>步骤 5</td><td>范围遗漏</td><td>步骤 4（补充计划后重新确认）</td></tr><tr><td>步骤 5.5a</td><td>🔴 必须修复项</td><td>就地修复 → 重新审查该文件</td></tr><tr><td>步骤 5.5c</td><td>Lint/编译错误</td><td>直接修复 → 回 5.5a 审查修复代码</td></tr><tr><td>步骤 6A V1/V2/V3</td><td>编译/类型/Lint 错误</td><td>直接修复 → 即时验证 → 回 5.5a 审查修复代码</td></tr><tr><td>步骤 6A V4</td><td>Browser 验证失败</td><td>分析原因 → 回步骤 5 修复 → 重走 5.5（审查+自检）→ 6A</td></tr><tr><td>步骤 6A V5</td><td>测试失败</td><td>分析原因 → 回步骤 3 重新制定方案 → 4 → 5 → 5.5 → 6A</td></tr><tr><td>步骤 6A V6</td><td>安全问题</td><td>直接修复 → 即时验证 → 回 5.5a 审查修复代码</td></tr><tr><td>步骤 6A V7</td><td>预期外变更</td><td>清理 → 即时验证 → 回 5.5a 审查</td></tr><tr><td>步骤 6B</td><td>用户跳过验收</td><td>进入 6C 联调判断（或直接步骤 7）</td></tr><tr><td>步骤 6B</td><td>部分问题</td><td>清理调试代码 → 步骤 5（修复后重新走 5.5 → 6A → 6B）</td></tr><tr><td>步骤 6B</td><td>验收不通过</td><td>清理调试代码 → 步骤 3（重新制定方案）</td></tr><tr><td>步骤 6C</td><td>用户跳过联调</td><td>清理调试代码 → 直接进入步骤 7</td></tr><tr><td>步骤 6C</td><td>后端未就绪</td><td>暂存前置处理（清理/Commit 可选）→ 暂存等联调 → 更新工作上下文 → 等待恢复信号</td></tr><tr><td>步骤 6C</td><td>前端问题</td><td>回退步骤 5 修复 → 5.5 → 6A → 继续 6C</td></tr><tr><td>步骤 6C</td><td>后端问题</td><td>记录问题 → 暂存等后端修复 → 恢复后继续 6C</td></tr><tr><td>步骤 6C</td><td>协议不一致</td><td>前后端协商 → 可能回退步骤 3 重新制定方案</td></tr><tr><td>步骤 6C</td><td>联调通过</td><td>清理调试代码 → 步骤 7</td></tr><tr><td>步骤 7</td><td>清理调试代码后编译异常</td><td>即时验证 → 回 5.5c 自检 → 修复 → 回 5.5a 审查</td></tr><tr><td>步骤 7</td><td>L2 审查 🔴 修复后</td><td>即时验证 → 回 5.5a 审查修复代码 → 5.5c 自检 → 重新 L2</td></tr><tr><td>步骤 6→7 之间</td><td>用户验收/实际测试中发现新问题</td><td>修复 → 重走 5.5 → 6 → 7（完整链路，步骤 7 必须完整执行 A~J 环节）</td></tr></tbody></table><h2 id="批次执行回退机制" tabindex="-1">批次执行回退机制 <a class="header-anchor" href="#批次执行回退机制" aria-label="Permalink to &quot;批次执行回退机制&quot;">​</a></h2><blockquote><p>批次模式下的回退规则。批次内部回退不影响其他批次，跨批次回退需重新评估批次规划。</p></blockquote><table tabindex="0"><thead><tr><th>当前步骤</th><th>问题</th><th>回退到</th></tr></thead><tbody><tr><td>步骤 4</td><td>用户选择「分批执行」后要求调整批次划分</td><td>步骤 4（更新批次规划后重新弹出选项）</td></tr><tr><td>Batch N 步骤 5</td><td>当前批次计划无法执行</td><td>步骤 4（暂停当前批次，说明原因，重新评估批次规划）</td></tr><tr><td>Batch N 步骤 5</td><td>发现需要修改已完成批次的代码</td><td>记录为跨批次依赖问题 → 在当前批次中修复 → 更新已完成批次的 devlog</td></tr><tr><td>Batch N 步骤 6</td><td>验证失败，根因在已完成批次</td><td>在当前批次中修复 → 重走 5.5 → 6A（不回退已完成批次）</td></tr><tr><td>Batch N 步骤 6</td><td>验证失败，需要重新制定方案</td><td>回退步骤 3 → 重新评估是否仍需分批 + 重新规划批次</td></tr><tr><td>Batch N 步骤 7</td><td>批次 commit 后发现问题</td><td>在下一批次中修复（原子提交原则，不修改已提交的批次）</td></tr><tr><td>批次切换</td><td>用户要求跳过某个批次</td><td>标记该批次为 skipped → 继续下一批次 → 最后一批时评估是否需要补回</td></tr><tr><td>批次切换</td><td>用户要求重做某个已完成批次</td><td>回退该批次状态为 in_progress → 重新执行 4.5→5→5.5→6→7</td></tr></tbody></table><h2 id="回退触发的交互式选项汇总" tabindex="-1">回退触发的交互式选项汇总 <a class="header-anchor" href="#回退触发的交互式选项汇总" aria-label="Permalink to &quot;回退触发的交互式选项汇总&quot;">​</a></h2><blockquote><p>本章节抽取各步骤&quot;发现问题 → 弹选项让用户决策&quot;的通用交互式选项模板，供各步骤 cross-ref。 所有选项必须遵循 <code>~/.codebuddy/rules/AI行为规范.mdc</code> §「交互式选项一致性规则」的双重展示要求（文本表格 + <code>ask_followup_question</code>）。 ⚠️ <strong>重要</strong>：以下模板是<strong>通用参考范本</strong>，各步骤的实际选项<strong>可按场景裁剪</strong>（增删选项、调整文案），但必须满足：</p><ol><li>保留至少 2 个合理选项（不能只给一个选项）</li><li>选项覆盖主要决策路径（继续 / 回退 / 终止 三类中至少两类）</li><li>裁剪后仍符合「交互式选项一致性规则」的双重展示要求</li></ol></blockquote><h3 id="通用模板-a-验证失败-执行受阻-3-次熔断、计划无法执行等" tabindex="-1">通用模板 A：验证失败 / 执行受阻（3 次熔断、计划无法执行等） <a class="header-anchor" href="#通用模板-a-验证失败-执行受阻-3-次熔断、计划无法执行等" aria-label="Permalink to &quot;通用模板 A：验证失败 / 执行受阻（3 次熔断、计划无法执行等）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>🔄 回退重做</td><td>回到步骤 {N} 重新执行（N 按上方回退对照表确定）</td></tr><tr><td>🛠️ 我来处理</td><td>暂停流程，由我手动处理后告知你继续</td></tr><tr><td>⏭️ 跳过此阶段</td><td>忽略该阶段（仅非关键阶段允许，熔断时谨慎使用）</td></tr><tr><td>❌ 终止</td><td>终止本次任务</td></tr></tbody></table><p><strong>适用场景</strong>：step-5 计划无法执行、step-6A 3 次失败熔断、step-6C 前后端问题。</p><h3 id="通用模板-b-质量审查-🟡-建议修复项" tabindex="-1">通用模板 B：质量审查 🟡 建议修复项 <a class="header-anchor" href="#通用模板-b-质量审查-🟡-建议修复项" aria-label="Permalink to &quot;通用模板 B：质量审查 🟡 建议修复项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>🔧 全部修复</td><td>修复所有 🟡 建议项</td></tr><tr><td>⏭️ 全部跳过</td><td>跳过所有 🟡 建议项</td></tr><tr><td>✏️ 部分修复</td><td>告诉我要修复哪几项（如 &quot;修 1,3&quot;）</td></tr></tbody></table><p><strong>适用场景</strong>：step-5.5a L1 审查、步骤 7 环节 G L2 审查。</p><h3 id="通用模板-c-清理-回退类" tabindex="-1">通用模板 C：清理/回退类 <a class="header-anchor" href="#通用模板-c-清理-回退类" aria-label="Permalink to &quot;通用模板 C：清理/回退类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>🧹 全部回退/清理</td><td>对所有预期外文件/遗留调试代码执行处理</td></tr><tr><td>✏️ 部分回退/清理</td><td>告诉我保留哪几项</td></tr><tr><td>⏭️ 保留全部 / 跳过</td><td>不做处理，继续下一步</td></tr></tbody></table><p><strong>适用场景</strong>：步骤 7 环节 A 预期外变更、步骤 7 环节 B 调试代码清理。</p><h3 id="通用模板-d-步骤流转推进选项-每步骤完成后" tabindex="-1">通用模板 D：步骤流转推进选项（每步骤完成后） <a class="header-anchor" href="#通用模板-d-步骤流转推进选项-每步骤完成后" aria-label="Permalink to &quot;通用模板 D：步骤流转推进选项（每步骤完成后）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>▶️ 继续步骤 {N+1}（{步骤名}）</td><td>门控已通过，进入下一步</td></tr><tr><td>⏸️ 暂停，我有补充/疑问</td><td>暂停等待用户输入</td></tr><tr><td>🔁 回退步骤 {N} 重新执行</td><td>本步骤有遗漏，重做</td></tr></tbody></table><p><strong>适用场景</strong>：所有步骤完成后（精简模式豁免见 <code>steps/step-router.md</code> §步骤流转交互规则）。</p><h3 id="通用模板-e-暂存-取消终态" tabindex="-1">通用模板 E：暂存/取消终态 <a class="header-anchor" href="#通用模板-e-暂存-取消终态" aria-label="Permalink to &quot;通用模板 E：暂存/取消终态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>⏸️ 暂存</td><td>锁定当前进度，写入工作上下文，结束当前会话</td></tr><tr><td>❌ 取消</td><td>终止本次任务，不保留进度</td></tr></tbody></table><p><strong>适用场景</strong>：step-4 用户决策、需要用户中断的任何场景。</p>',24)])])}const u=d(o,[["render",l]]);export{p as __pageData,u as default};
